def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def select(d,keys):return {k:d[k] for k in keys.split() if k in d}
def verify_inputs(base):
 for m in base.rglob('manifest.json'):
  for r in read(m)['files']:
   p=m.parent/r['path'];b=p.read_bytes();assert len(b)==r['bytes'] and hashlib.sha256(b).hexdigest()==r['sha256'],str(p)
def clean_text(x):
 if isinstance(x,dict):return {k:clean_text(v) for k,v in x.items()}
 if isinstance(x,list):return [clean_text(v) for v in x]
 if isinstance(x,str):
  # Readability-only normalization; source URLs, identifiers and exact headings stay unchanged.
  for a,b in [('suggestMay 1','suggest May 1'),('event-indexURLs','event-index URLs'),('recordings.2025','recordings. 2025'),('writingURLs','writing URLs'),('Sundays.2022','Sundays. 2022'),('calendarSundays','calendar Sundays'),('Noaudio','No audio'),('ortranscribed','or transcribed'),('andtwo','and two')]:x=x.replace(a,b)
 return x

