def dumps(x):return json.dumps(x,ensure_ascii=False,indent=2)+'\n'
def csv_value(v):
 if v is None:return ''
 if isinstance(v,(dict,list,bool)):return json.dumps(v,ensure_ascii=False,separators=(',',':'))
 s=str(v)
 return "'"+s if re.match(r'^\s*[=+@-]',s) else s
def write_csv(p,records):
 fields=list(dict.fromkeys(k for r in records for k in r))
 out=io.StringIO(newline='');w=csv.DictWriter(out,fieldnames=fields);w.writeheader();w.writerows([{k:csv_value(r.get(k)) for k in fields} for r in records]);p.write_text('\ufeff'+out.getvalue(),encoding='utf-8')
